// The patch manifest: umbrella ticket 08's schema, in C#.
//
// Generated by tools/re-static/gen_manifest.py, checked into git as the
// reviewable source of truth, embedded here as a resource, and guarded at build
// time by a regenerate-and-diff step.  Nothing in this file decides anything --
// it is the authoring-time record of what APE writes and where.
//
// Vocabulary (ticket 08):
//   patch  the checkbox-toggleable unit; unchecking reverts it as a whole
//   site   one write location -- one address in sh3.exe, one ValN line in
//          hsie.ini, or one keyed line in data/Menu/en_menu.txt (ticket 10) --
//          carrying exactly one field
//
// Every site holds its complete original byte run or line, not merely enough to
// verify: unchecking is the only revert mechanism APE has, and it has to
// reconstruct the exact pre-APE state.

using System;
using System.Collections.Generic;
using System.Globalization;
using System.IO;
using System.Reflection;
using System.Text;

namespace ApePatcher
{
    public class PatchException : Exception
    {
        public PatchException(string message) : base(message) { }
        public PatchException(string message, Exception inner) : base(message, inner) { }
    }

    public enum SiteStore { Sh3Exe, HsieIni, MenuText }

    public enum FieldEncoding { Byte, Float32, OperandImmediate, FixedRewrite, IniValue }

    /// <summary>Where a site's value comes from in the desired-state model. Drives
    /// the write in one direction and the read-back in the other.</summary>
    public enum Source
    {
        None,
        HullWidth, HullFloor,
        BandLo, BandHi,
        Pdso, Threshold,
        Literal
    }

    public class Site
    {
        public string Id;
        public SiteStore Store;
        public FieldEncoding Encoding;
        public Source Source = Source.None;
        public string Note;

        // sh3.exe sites
        public string Va;
        public int Offset;
        public byte[] Original;                   // the complete original run
        public byte[] Replacement;                // fixed-rewrite only
        public List<KeyValuePair<int, byte[]>> Context = new List<KeyValuePair<int, byte[]>>();
        public int FieldAt = -1;
        public int FieldLength;
        public string FieldType;                  // "u8", "u32", "f32"

        // The field's authored validity range (ticket 06) -- what the manifest
        // proved the site accepts, not APE's own product opinion about what to
        // ship. Unset (NaN) for a site with no field at all.
        public double Min = double.NaN;
        public double Max = double.NaN;
        public bool HasRange { get { return !double.IsNaN(Min); } }

        // hsie.ini and en_menu.txt sites -- both a keyed "key=value" line in a
        // plain-text file, captured/written/reverted by exact-text round trip.
        public string Key;
        public string OriginalLine;
        public string LiteralValue;               // for Source.Literal

        public bool HasField { get { return FieldAt >= 0; } }

        /// <summary>A human-readable name for this site, used when a verification
        /// failure has to be diagnosable.</summary>
        public string Describe()
        {
            switch (Store)
            {
                case SiteStore.HsieIni: return "hsie.ini " + Key;
                case SiteStore.MenuText: return "data/Menu/en_menu.txt " + Key;
                default: return "sh3.exe " + Va + " (" + Id + ")";
            }
        }
    }

    public class Patch
    {
        public string Id;
        public string Name;
        /// <summary>1-based index into h.sie's flag table, or 0 for no dependency.
        /// APE reads that table and never writes it (ticket 05, decision A-2).</summary>
        public int FlagIndex;
        public List<Site> Sites = new List<Site>();

        public IEnumerable<Site> SitesIn(SiteStore store)
        {
            foreach (Site s in Sites) if (s.Store == store) yield return s;
        }
    }

    public class Manifest
    {
        public const string HullPatchId = "hull-repair";
        public const string DieselPatchId = "diesel-damage";

        public int Schema;
        public int FlagTableOffset;
        public int FlagCount;
        public int VersionStringOffset;
        public int VersionStringLength;
        public List<Patch> Patches = new List<Patch>();

        public Patch Patch(string id)
        {
            foreach (Patch p in Patches)
                if (string.Equals(p.Id, id, StringComparison.Ordinal)) return p;
            throw new PatchException("Manifest has no patch '" + id + "'.");
        }

        // -- loading -----------------------------------------------------------

        public const string ResourceName = "ape-manifest.json";

        static string embeddedJson;

        public static string EmbeddedJson()
        {
            if (embeddedJson != null) return embeddedJson;
            Assembly asm = Assembly.GetExecutingAssembly();
            using (Stream s = asm.GetManifestResourceStream(ResourceName))
            {
                if (s == null)
                    throw new PatchException("APE was built without its patch manifest. "
                        + "This build cannot write anything.");
                using (StreamReader r = new StreamReader(s, System.Text.Encoding.UTF8))
                    embeddedJson = r.ReadToEnd();
            }
            return embeddedJson;
        }

        /// <summary>A fresh manifest off the embedded resource.</summary>
        public static Manifest Embedded()
        {
            return FromJson(EmbeddedJson());
        }

        public static Manifest FromJson(string json)
        {
            Dictionary<string, object> root = Json.Obj(Json.Parse(json));
            Manifest m = new Manifest();
            m.Schema = Json.Int(root, "schema");
            if (m.Schema != 2)
                throw new PatchException("Manifest schema " + Fmt.Int(m.Schema)
                    + " is not one this build of APE understands.");
            m.FlagTableOffset = Json.Int(root, "flagTableOffset");
            m.FlagCount = Json.Int(root, "flagCount");
            m.VersionStringOffset = Json.Int(root, "versionStringOffset");
            m.VersionStringLength = Json.Int(root, "versionStringLength");

            foreach (object o in Json.Arr(Json.Get(root, "patches")))
            {
                Dictionary<string, object> p = Json.Obj(o);
                Patch patch = new Patch();
                patch.Id = Json.Str(p, "id");
                patch.Name = Json.Str(p, "name");
                object flag = Json.Get(p, "flagIndex");
                patch.FlagIndex = flag == null ? 0 : (int)Math.Round((double)flag);
                foreach (object so in Json.Arr(Json.Get(p, "sites")))
                    patch.Sites.Add(ReadSite(Json.Obj(so)));
                m.Patches.Add(patch);
            }
            return m;
        }

        static Site ReadSite(Dictionary<string, object> s)
        {
            Site site = new Site();
            site.Id = Json.Str(s, "id");
            site.Note = Json.Str(s, "note");
            string store = Json.Str(s, "store");
            site.Store = store == "hsie.ini" ? SiteStore.HsieIni
                        : store == "en_menu.txt" ? SiteStore.MenuText
                        : SiteStore.Sh3Exe;
            site.Encoding = ParseEncoding(Json.Str(s, "encoding"));

            if (site.Store != SiteStore.Sh3Exe)
            {
                site.Key = Json.Str(s, "key");
                site.OriginalLine = Json.Str(s, "original");
                Dictionary<string, object> ape = Json.Obj(Json.Get(s, "ape"));
                string kind = Json.Str(ape, "kind");
                if (kind == "literal")
                {
                    site.Source = Source.Literal;
                    site.LiteralValue = Json.Str(ape, "value");
                }
                else
                {
                    site.Source = ParseSource(Json.Str(ape, "source"));
                }
                return site;
            }

            site.Va = Json.Str(s, "va");
            site.Original = Hex.ToBytes(Json.Str(s, "original"));
            string rep = Json.Str(s, "replacement");
            if (rep != null) site.Replacement = Hex.ToBytes(rep);
            string src = Json.Str(s, "source");
            if (src != null) site.Source = ParseSource(src);

            foreach (object co in Json.Arr(Json.Get(s, "context")))
            {
                List<object> pair = Json.Arr(co);
                site.Context.Add(new KeyValuePair<int, byte[]>(
                    (int)Math.Round((double)pair[0]), Hex.ToBytes((string)pair[1])));
            }

            site.Offset = Json.Int(s, "offset");

            object f = Json.Get(s, "field");
            if (f != null)
            {
                Dictionary<string, object> fd = Json.Obj(f);
                site.FieldAt = Json.Int(fd, "at");
                site.FieldLength = Json.Int(fd, "length");
                site.FieldType = Json.Str(fd, "type");
            }
            if (Json.Get(s, "min") != null)
            {
                site.Min = Json.Num(s, "min");
                site.Max = Json.Num(s, "max");
            }
            return site;
        }

        static FieldEncoding ParseEncoding(string s)
        {
            switch (s)
            {
                case "byte": return FieldEncoding.Byte;
                case "float32": return FieldEncoding.Float32;
                case "operand-immediate": return FieldEncoding.OperandImmediate;
                case "fixed-rewrite": return FieldEncoding.FixedRewrite;
                case "ini-value": return FieldEncoding.IniValue;
            }
            throw new PatchException("Manifest declares an unknown field encoding '" + s + "'.");
        }

        static Source ParseSource(string s)
        {
            switch (s)
            {
                case "hull_width": return Source.HullWidth;
                case "hull_floor": return Source.HullFloor;
                case "band_lo": return Source.BandLo;
                case "band_hi": return Source.BandHi;
                case "p_dso": return Source.Pdso;
                case "threshold": return Source.Threshold;
            }
            throw new PatchException("Manifest declares an unknown value source '" + s + "'.");
        }
    }

    public static class Hex
    {
        public static byte[] ToBytes(string hex)
        {
            if (hex == null) return null;
            if ((hex.Length & 1) != 0)
                throw new PatchException("Manifest holds an odd-length byte run.");
            byte[] b = new byte[hex.Length / 2];
            for (int i = 0; i < b.Length; i++)
                b[i] = byte.Parse(hex.Substring(i * 2, 2), NumberStyles.HexNumber,
                                  CultureInfo.InvariantCulture);
            return b;
        }

        public static string ToString(byte[] bytes)
        {
            StringBuilder sb = new StringBuilder(bytes.Length * 2);
            foreach (byte b in bytes) sb.Append(b.ToString("x2", CultureInfo.InvariantCulture));
            return sb.ToString();
        }
    }
}
